CREATE TABLE public.application_access_sessions (user_id uuid NOT NULL, session_id uuid NOT NULL, scope text NOT NULL CHECK(scope IN ('screen','screen-bypass','dashboard','portal')), granted_at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL, last_activity_at timestamptz NOT NULL DEFAULT clock_timestamp(), locked boolean NOT NULL DEFAULT false, PRIMARY KEY(user_id,session_id,scope));
GRANT ALL ON public.application_access_sessions TO service_role;
ALTER TABLE public.application_access_sessions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.application_access_sessions FROM anon,authenticated;
CREATE FUNCTION public.application_scope_open(p_scope text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM public.application_access_sessions s WHERE s.user_id=auth.uid() AND s.session_id=public.profile_auth_session_id() AND s.scope=p_scope AND NOT s.locked AND s.expires_at>now() AND (p_scope<>'portal' OR NOT EXISTS(SELECT 1 FROM public.customer_portals p WHERE p.user_id=s.user_id AND p.reset_at>=s.granted_at))); $$;
REVOKE ALL ON FUNCTION public.application_scope_open(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.application_scope_open(text) TO authenticated,service_role;
CREATE FUNCTION public.application_screen_open() RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE s public.application_access_sessions; timeout integer; enabled boolean; started timestamptz; BEGIN IF auth.uid() IS NULL THEN RETURN false; END IF; IF public.application_scope_open('screen-bypass') THEN RETURN true; END IF; SELECT x.enabled,x.timeout_minutes INTO enabled,timeout FROM public.screen_lock_settings x WHERE x.user_id=auth.uid(); IF enabled IS FALSE THEN RETURN true; END IF; timeout:=greatest(1,coalesce(timeout,5)); SELECT * INTO s FROM public.application_access_sessions WHERE user_id=auth.uid() AND session_id=public.profile_auth_session_id() AND scope='screen'; IF FOUND THEN RETURN NOT s.locked AND s.last_activity_at+make_interval(mins=>timeout)>now(); END IF; SELECT created_at INTO started FROM auth.sessions WHERE id=public.profile_auth_session_id() AND user_id=auth.uid(); RETURN coalesce(started+make_interval(mins=>timeout)>now(),false); END $$;
REVOKE ALL ON FUNCTION public.application_screen_open() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.application_screen_open() TO authenticated,service_role;
CREATE FUNCTION public.application_screen_status(p_activity boolean DEFAULT false,p_lock boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE started timestamptz; timeout integer; enabled boolean; opened boolean; BEGIN IF auth.uid() IS NULL OR public.profile_auth_session_id() IS NULL THEN RAISE EXCEPTION 'Sign in again'; END IF; SELECT created_at INTO started FROM auth.sessions WHERE id=public.profile_auth_session_id() AND user_id=auth.uid(); IF started IS NULL THEN RAISE EXCEPTION 'Sign in again'; END IF; SELECT x.enabled,x.timeout_minutes INTO enabled,timeout FROM public.screen_lock_settings x WHERE x.user_id=auth.uid(); timeout:=greatest(1,coalesce(timeout,5)); opened:=public.application_screen_open(); INSERT INTO public.application_access_sessions(user_id,session_id,scope,expires_at,last_activity_at,locked) VALUES(auth.uid(),public.profile_auth_session_id(),'screen',started+make_interval(mins=>timeout),started,NOT opened) ON CONFLICT DO NOTHING; IF p_lock THEN UPDATE public.application_access_sessions SET locked=true WHERE user_id=auth.uid() AND session_id=public.profile_auth_session_id() AND scope='screen'; ELSIF p_activity AND opened THEN UPDATE public.application_access_sessions SET last_activity_at=clock_timestamp(),expires_at=clock_timestamp()+make_interval(mins=>timeout) WHERE user_id=auth.uid() AND session_id=public.profile_auth_session_id() AND scope='screen' AND NOT locked; END IF; RETURN jsonb_build_object('open',NOT p_lock AND public.application_screen_open(),'enabled',coalesce(enabled,true),'timeout_minutes',timeout); END $$;
REVOKE ALL ON FUNCTION public.application_screen_status(boolean,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.application_screen_status(boolean,boolean) TO authenticated,service_role;
CREATE FUNCTION public.application_portal_required() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,private,pg_catalog AS $$ SELECT auth.uid() IS NOT NULL AND NOT (NOT public.customer_profile_restricted() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('admin','management','staff','moderator'))) AND NOT EXISTS(SELECT 1 FROM private.app_credentials WHERE owner_id=auth.uid()); $$;
REVOKE ALL ON FUNCTION public.application_portal_required() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.application_portal_required() TO authenticated,service_role;
CREATE FUNCTION public.application_access_status() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$ SELECT jsonb_build_object('screen',public.application_screen_open(),'dashboard',public.application_scope_open('dashboard'),'portal',NOT public.application_portal_required() OR public.application_scope_open('portal'),'dashboardUntil',(SELECT expires_at FROM public.application_access_sessions WHERE user_id=auth.uid() AND session_id=public.profile_auth_session_id() AND scope='dashboard' AND NOT locked AND expires_at>now()),'portalUntil',(SELECT expires_at FROM public.application_access_sessions WHERE user_id=auth.uid() AND session_id=public.profile_auth_session_id() AND scope='portal' AND public.application_scope_open('portal'))); $$;
REVOKE ALL ON FUNCTION public.application_access_status() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.application_access_status() TO authenticated,service_role;
CREATE FUNCTION public.application_revoke_dashboard() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ UPDATE public.application_access_sessions SET locked=true WHERE user_id=auth.uid() AND session_id=public.profile_auth_session_id() AND scope='dashboard'; $$;
REVOKE ALL ON FUNCTION public.application_revoke_dashboard() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.application_revoke_dashboard() TO authenticated,service_role;
CREATE FUNCTION public.application_consume_backup(p_user uuid,p_hash text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE used uuid; BEGIN UPDATE public.admin_backup_codes SET used_at=clock_timestamp() WHERE user_id=p_user AND code_hash=p_hash AND used_at IS NULL RETURNING id INTO used; RETURN used IS NOT NULL; END $$;
REVOKE ALL ON FUNCTION public.application_consume_backup(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.application_consume_backup(uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.portal_verify_login_code(p_user_id uuid,p_code_hash text) RETURNS timestamptz LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE r public.customer_portal_login_codes; v_until timestamptz; BEGIN SELECT * INTO r FROM public.customer_portal_login_codes WHERE user_id=p_user_id FOR UPDATE; IF NOT FOUND OR r.expires_at<=now() OR r.failed_attempts>=5 THEN RETURN NULL; END IF; IF NOT EXISTS(SELECT 1 FROM public.customer_portals p WHERE p.user_id=p_user_id AND (p.reset_at IS NULL OR p.reset_at<r.issued_at)) THEN RETURN NULL; END IF; IF r.code_hash<>p_code_hash THEN UPDATE public.customer_portal_login_codes SET failed_attempts=failed_attempts+1 WHERE user_id=p_user_id; RETURN NULL; END IF; v_until:=least(clock_timestamp()+interval '1 hour',r.expires_at); UPDATE public.customer_portals SET unlocked_until=v_until WHERE user_id=p_user_id; RETURN v_until; END $$;
REVOKE ALL ON FUNCTION public.portal_verify_login_code(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.portal_verify_login_code(uuid,text) TO service_role;
CREATE FUNCTION public.application_request_guard() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE path text:=coalesce(current_setting('request.path',true),''); method text:=coalesce(current_setting('request.method',true),''); resource text; safe boolean; BEGIN IF auth.uid() IS NULL OR auth.role()='service_role' THEN RETURN; END IF; resource:=regexp_replace(path,'^/(rest/v1/)?',''); safe:=resource IN ('rpc/application_access_status','rpc/application_screen_status','rpc/application_revoke_dashboard','rpc/customer_profile_restricted','rpc/my_profile_access','rpc/active_profile_credential','rpc/get_customer_number','rpc/check_admin_unlock_lockout','rpc/record_admin_unlock_failure') OR (method IN ('GET','HEAD') AND resource IN ('profiles','user_roles','password_change_required','screen_lock_settings','page_permissions','fan_zone_members','site_settings','app_settings')) OR resource IN ('user_notifications','staff_notifications','staff_notification_reads'); IF NOT safe AND NOT public.application_screen_open() THEN RAISE sqlstate 'PT423' USING message='Unlock your screen before continuing.'; END IF; IF (resource LIKE 'rpc/admin_%' OR resource IN ('admin_backup_codes','manual_name_customers','manual_customer_names','customer_account_packages','customer_package_allocations','customer_renewal_date_corrections','customer_account_renewal_dates')) AND resource NOT IN ('rpc/check_admin_unlock_lockout','rpc/record_admin_unlock_failure') AND NOT public.application_scope_open('dashboard') THEN RAISE sqlstate 'PT403' USING message='Unlock your dashboard before continuing.'; END IF; IF public.application_portal_required() AND NOT public.application_scope_open('portal') AND (resource IN ('orders','order_items','order_messages','tickets','ticket_messages','app_credentials','qd_dns_codes','invites','referral_credit_ledger') OR resource LIKE 'rpc/portal_%' OR resource LIKE 'rpc/claim_checkout%' OR resource LIKE 'rpc/referral_%' OR resource='rpc/player_owner_saved_logins') THEN RAISE sqlstate 'PT403' USING message='Enter your emailed portal code before continuing.'; END IF; END $$;
REVOKE ALL ON FUNCTION public.application_request_guard() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.application_request_guard() TO authenticated,service_role;
ALTER ROLE authenticator SET pgrst.db_pre_request='public.application_request_guard';
NOTIFY pgrst,'reload config';
NOTIFY pgrst,'reload schema';
COMMENT ON COLUMN public.customer_portals.unlocked_until IS 'Legacy account-level expiry; authorization uses session-bound application_access_sessions instead.';